74: /**
75:  * A manager for dealing with catalog objects such as tables, views, functions, and types. It
76:  * encapsulates all available catalogs and stores temporary objects.
77:  */
78: @Internal
79: public final class CatalogManager implements CatalogRegistry, AutoCloseable {
80:     private static final Logger LOG = LoggerFactory.getLogger(CatalogManager.class);
81: 
82:     // A map between names and catalogs.
83:     private final Map<String, Catalog> catalogs;
84: 
85:     // Those tables take precedence over corresponding permanent tables, thus they shadow
86:     // tables coming from catalogs.
87:     private final Map<ObjectIdentifier, CatalogBaseTable> temporaryTables;
88: 
89:     // The name of the current catalog and database
90:     private @Nullable String currentCatalogName;
91: 
92:     private @Nullable String currentDatabaseName;
93: 
94:     private DefaultSchemaResolver schemaResolver;
95: 
96:     // The name of the built-in catalog
97:     private final String builtInCatalogName;
98: 
99:     private final DataTypeFactory typeFactory;
100: 
101:     private final ManagedTableListener managedTableListener;
102: 
103:     private final List<CatalogModificationListener> catalogModificationListeners;
104: 
105:     private final CatalogStoreHolder catalogStoreHolder;
106: 
107:     private CatalogManager(
108:             String defaultCatalogName,
109:             Catalog defaultCatalog,
110:             DataTypeFactory typeFactory,
111:             ManagedTableListener managedTableListener,
112:             List<CatalogModificationListener> catalogModificationListeners,
113:             CatalogStoreHolder catalogStoreHolder) {
114:         checkArgument(
115:                 !StringUtils.isNullOrWhitespaceOnly(defaultCatalogName),
116:                 "Default catalog name cannot be null or empty");
117:         checkNotNull(defaultCatalog, "Default catalog cannot be null");
118: 
119:         catalogs = new LinkedHashMap<>();
120:         catalogs.put(defaultCatalogName, defaultCatalog);
121:         currentCatalogName = defaultCatalogName;
122:         currentDatabaseName = defaultCatalog.getDefaultDatabase();
123: 
124:         temporaryTables = new HashMap<>();
125:         // right now the default catalog is always the built-in one
126:         builtInCatalogName = defaultCatalogName;
127: 
128:         this.typeFactory = typeFactory;
129:         this.managedTableListener = managedTableListener;
130:         this.catalogModificationListeners = catalogModificationListeners;
131: 
132:         this.catalogStoreHolder = catalogStoreHolder;
133:     }
134: 
135:     @VisibleForTesting
136:     public List<CatalogModificationListener> getCatalogModificationListeners() {
137:         return catalogModificationListeners;
138:     }
