228:             String catalogName = entry.getKey();
229:             Catalog catalog = entry.getValue();
230:             try {
231:                 catalog.close();
232:             } catch (Throwable e) {
233:                 LOG.error(
234:                         String.format(
235:                                 "Failed to close catalog %s: %s", catalogName, e.getMessage()),
236:                         e);
237:                 errors.add(e);
238:             }
239:         }
240: 
241:         // close the catalog store holder
242:         try {
243:             catalogStoreHolder.close();
244:         } catch (Throwable e) {
245:             errors.add(e);
246:             LOG.error(String.format("Failed to close catalog store holder: %s", e.getMessage()), e);
247:         }
248: 
249:         if (!errors.isEmpty()) {
250:             CatalogException exception = new CatalogException("Failed to close catalog manager");
251:             for (Throwable e : errors) {
252:                 exception.addSuppressed(e);
253:             }
254:             throw exception;
255:         }
256:     }
