347:     /**
348:      * Unregisters a catalog under the given name. The catalog name must be existed.
349:      *
350:      * <p>If the catalog is in the initialized catalogs, it will be removed from the initialized
351:      * catalogs. If the catalog is stored in the {@link CatalogStore}, it will be removed from the
352:      * CatalogStore.
353:      *
354:      * @param catalogName name under which to unregister the given catalog.
355:      * @param ignoreIfNotExists If false exception will be thrown if the table or database or
356:      *     catalog to be altered does not exist.
357:      * @throws CatalogException If the catalog does not exist in the initialized catalogs and not in
358:      *     the {@link CatalogStore}, or if the remove operation failed.
359:      */
360:     public void unregisterCatalog(String catalogName, boolean ignoreIfNotExists) {
361:         checkArgument(
362:                 !StringUtils.isNullOrWhitespaceOnly(catalogName),
363:                 "Catalog name cannot be null or empty.");
364: 
365:         if (catalogs.containsKey(catalogName)
366:                 || catalogStoreHolder.catalogStore().contains(catalogName)) {
367:             if (catalogName.equals(currentCatalogName)) {
368:                 throw new CatalogException("Cannot drop a catalog which is currently in use.");
369:             }
370:             if (catalogs.containsKey(catalogName)) {
371:                 Catalog catalog = catalogs.remove(catalogName);
372:                 catalog.close();
373:             }
374:             if (catalogStoreHolder.catalogStore().contains(catalogName)) {
375:                 catalogStoreHolder.catalogStore().removeCatalog(catalogName, ignoreIfNotExists);
376:             }
377:         } else if (!ignoreIfNotExists) {
378:             throw new CatalogException(format("Catalog %s does not exist.", catalogName));
379:         }
380:     }
