649:     private Optional<ContextResolvedTable> getPermanentTable(
650:             ObjectIdentifier objectIdentifier, @Nullable Long timestamp) {
651:         Optional<Catalog> catalogOptional = getCatalog(objectIdentifier.getCatalogName());
652:         ObjectPath objectPath = objectIdentifier.toObjectPath();
653:         if (catalogOptional.isPresent()) {
654:             Catalog currentCatalog = catalogOptional.get();
655:             try {
656:                 final CatalogBaseTable table;
657:                 if (timestamp != null) {
658:                     table = currentCatalog.getTable(objectPath, timestamp);
659:                     if (table.getTableKind() == CatalogBaseTable.TableKind.VIEW) {
660:                         throw new TableException(
661:                                 String.format(
662:                                         "%s is a view, but time travel is not supported for view.",
663:                                         objectIdentifier.asSummaryString()));
664:                     }
665:                 } else {
666:                     table = currentCatalog.getTable(objectPath);
667:                 }
668:                 final ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(table);
669:                 return Optional.of(
670:                         ContextResolvedTable.permanent(
671:                                 objectIdentifier, currentCatalog, resolvedTable));
672:             } catch (TableNotExistException e) {
673:                 // Ignore.
674:             }
675:         }
676:         return Optional.empty();
677:     }
