682:         if (currentCatalog.isPresent()) {
683:             try {
684:                 final CatalogBaseTable table = currentCatalog.get().getTable(objectPath);
685:                 return Optional.of(table);
686:             } catch (TableNotExistException e) {
687:                 // Ignore.
688:             }
689:         }
690:         return Optional.empty();
691:     }
