1084:     private void dropTemporaryTableInternal(
1085:             ObjectIdentifier objectIdentifier,
1086:             Predicate<CatalogBaseTable> filter,
1087:             boolean ignoreIfNotExists,
1088:             boolean isDropTable) {
1089:         CatalogBaseTable catalogBaseTable = temporaryTables.get(objectIdentifier);
1090:         if (filter.test(catalogBaseTable)) {
1091:             getTemporaryOperationListener(objectIdentifier)
1092:                     .ifPresent(l -> l.onDropTemporaryTable(objectIdentifier.toObjectPath()));
1093: 
1094:             Catalog catalog = getCatalog(objectIdentifier.getCatalogName()).orElse(null);
1095:             ResolvedCatalogBaseTable<?> resolvedTable = resolveCatalogBaseTable(catalogBaseTable);
1096:             managedTableListener.notifyTableDrop(
1097:                     catalog, objectIdentifier, resolvedTable, true, ignoreIfNotExists);
1098: 
1099:             temporaryTables.remove(objectIdentifier);
1100:             if (isDropTable) {
1101:                 catalogModificationListeners.forEach(
1102:                         listener ->
1103:                                 listener.onEvent(
1104:                                         DropTableEvent.createEvent(
1105:                                                 CatalogContext.createContext(
1106:                                                         objectIdentifier.getCatalogName(), catalog),
1107:                                                 objectIdentifier,
1108:                                                 resolvedTable,
1109:                                                 ignoreIfNotExists,
1110:                                                 true)));
1111:             }
1112:         } else if (!ignoreIfNotExists) {
1113:             throw new ValidationException(
1114:                     String.format(
1115:                             "Temporary table or view with identifier '%s' does not exist.",
1116:                             objectIdentifier.asSummaryString()));
1117:         }
1118:     }
