1235:         final Optional<CatalogBaseTable> resultOpt = getUnresolvedTable(objectIdentifier);
1236:         if (resultOpt.isPresent() && filter.test(resultOpt.get())) {
1237:             execute(
1238:                     (catalog, path) -> {
1239:                         ResolvedCatalogBaseTable<?> resolvedTable =
1240:                                 resolveCatalogBaseTable(resultOpt.get());
1241:                         managedTableListener.notifyTableDrop(
1242:                                 catalog, objectIdentifier, resolvedTable, false, ignoreIfNotExists);
