1307:     /** Resolves a {@link CatalogBaseTable} to a validated {@link ResolvedCatalogBaseTable}. */
1308:     public ResolvedCatalogBaseTable<?> resolveCatalogBaseTable(CatalogBaseTable baseTable) {
1309:         Preconditions.checkNotNull(schemaResolver, "Schema resolver is not initialized.");
1310:         if (baseTable instanceof CatalogTable) {
1311:             return resolveCatalogTable((CatalogTable) baseTable);
1312:         } else if (baseTable instanceof CatalogView) {
1313:             return resolveCatalogView((CatalogView) baseTable);
1314:         }
1315:         throw new IllegalArgumentException(
1316:                 "Unknown kind of catalog base table: " + baseTable.getClass());
