1319:     /** Resolves a {@link CatalogTable} to a validated {@link ResolvedCatalogTable}. */
1320:     public ResolvedCatalogTable resolveCatalogTable(CatalogTable table) {
1321:         Preconditions.checkNotNull(schemaResolver, "Schema resolver is not initialized.");
1322:         if (table instanceof ResolvedCatalogTable) {
1323:             return (ResolvedCatalogTable) table;
1324:         }
1325: 
1326:         final ResolvedSchema resolvedSchema = table.getUnresolvedSchema().resolve(schemaResolver);
1327: 
1328:         // Validate partition keys are included in physical columns
1329:         final List<String> physicalColumns =
1330:                 resolvedSchema.getColumns().stream()
1331:                         .filter(Column::isPhysical)
1332:                         .map(Column::getName)
1333:                         .collect(Collectors.toList());
1334:         table.getPartitionKeys()
1335:                 .forEach(
1336:                         partitionKey -> {
1337:                             if (!physicalColumns.contains(partitionKey)) {
1338:                                 throw new ValidationException(
1339:                                         String.format(
1340:                                                 "Invalid partition key '%s'. A partition key must "
1341:                                                         + "reference a physical column in the schema. "
1342:                                                         + "Available columns are: %s",
1343:                                                 partitionKey, physicalColumns));
1344:                             }
1345:                         });
1346: 
1347:         return new ResolvedCatalogTable(table, resolvedSchema);
1348:     }
