46: @Internal
47: public final class PojoSerializer<T> extends TypeSerializer<T> {
48: 
49:     // Flags for the header
50:     private static byte IS_NULL = 1;
51:     private static byte NO_SUBCLASS = 2;
52:     private static byte IS_SUBCLASS = 4;
53:     private static byte IS_TAGGED_SUBCLASS = 8;
54: 
55:     private static final long serialVersionUID = 1L;
56: 
57:     // --------------------------------------------------------------------------------------------
58:     // PojoSerializer parameters
59:     // --------------------------------------------------------------------------------------------
60: 
61:     /** The POJO type class. */
62:     private final Class<T> clazz;
63: 
64:     /**
65:      * Fields of the POJO and their serializers.
66:      *
67:      * <p>The fields are kept as a separate transient member, with their serialization handled with
68:      * the {@link #readObject(ObjectInputStream)} and {@link #writeObject(ObjectOutputStream)}
69:      * methods.
70:      */
71:     private transient Field[] fields;
72: 
73:     private final TypeSerializer<Object>[] fieldSerializers;
74:     private final int numFields;
75: 
76:     /**
77:      * Registered subclasses and their serializers. Each subclass to their registered class tag is
78:      * maintained as a separate map ordered by the class tag.
79:      */
80:     private final LinkedHashMap<Class<?>, Integer> registeredClasses;
81: 
82:     private final TypeSerializer<?>[] registeredSerializers;
83: 
84:     /** Cache of non-registered subclasses to their serializers, created on-the-fly. */
85:     private transient Map<Class<?>, TypeSerializer<?>> subclassSerializerCache;
86: 
87:     // --------------------------------------------------------------------------------------------
88: 
89:     /** Configuration of the current execution. */
90:     private final ExecutionConfig executionConfig;
91: 
92:     private transient ClassLoader cl;
93: 
94:     @Nullable private transient JavaRecordBuilderFactory<T> recordFactory;
95: 
96:     /** Constructor to create a new {@link PojoSerializer}. */
97:     @SuppressWarnings("unchecked")
98:     public PojoSerializer(
99:             Class<T> clazz,
100:             TypeSerializer<?>[] fieldSerializers,
101:             Field[] fields,
102:             ExecutionConfig executionConfig) {
103: 
104:         this.clazz = checkNotNull(clazz);
105:         this.fieldSerializers = (TypeSerializer<Object>[]) checkNotNull(fieldSerializers);
106:         this.fields = checkNotNull(fields);
107:         this.numFields = fieldSerializers.length;
108:         this.executionConfig = checkNotNull(executionConfig);
109: 
110:         for (int i = 0; i < numFields; i++) {
111:             this.fields[i].setAccessible(true);
112:         }
113: 
114:         this.cl = Thread.currentThread().getContextClassLoader();
115: 
116:         // We only want those classes that are not our own class and are actually sub-classes.
117:         LinkedHashSet<Class<?>> registeredSubclasses =
118:                 getRegisteredSubclassesFromExecutionConfig(clazz, executionConfig);
119: 
120:         this.registeredClasses = createRegisteredSubclassTags(registeredSubclasses);
121:         this.registeredSerializers =
122:                 createRegisteredSubclassSerializers(registeredSubclasses, executionConfig);
123: 
124:         this.subclassSerializerCache = new HashMap<>();
125:         if (TypeExtractor.isRecord(clazz)) {
126:             this.recordFactory = JavaRecordBuilderFactory.create(clazz, fields);
127:         }
128:     }
