130:     /**
131:      * Constructor to create a restore serializer or a reconfigured serializer from a {@link
132:      * PojoSerializerSnapshot}.
133:      */
134:     PojoSerializer(
135:             Class<T> clazz,
136:             Field[] fields,
137:             TypeSerializer<Object>[] fieldSerializers,
138:             LinkedHashMap<Class<?>, Integer> registeredClasses,
139:             TypeSerializer<?>[] registeredSerializers,
140:             Map<Class<?>, TypeSerializer<?>> subclassSerializerCache,
141:             ExecutionConfig executionConfig) {
142: 
143:         this.clazz = checkNotNull(clazz);
144:         this.fields = checkNotNull(fields);
145:         this.numFields = fields.length;
146:         this.fieldSerializers = checkNotNull(fieldSerializers);
147:         this.registeredClasses = checkNotNull(registeredClasses);
148:         this.registeredSerializers = checkNotNull(registeredSerializers);
149:         this.subclassSerializerCache = checkNotNull(subclassSerializerCache);
150:         this.executionConfig = checkNotNull(executionConfig);
151:         this.cl = Thread.currentThread().getContextClassLoader();
152:         if (TypeExtractor.isRecord(clazz)) {
153:             this.recordFactory = JavaRecordBuilderFactory.create(clazz, fields);
154:         }
155:     }
