414:     @Override
415:     @SuppressWarnings({"unchecked", "rawtypes"})
416:     public T deserialize(DataInputView source) throws IOException {
417:         int flags = source.readByte();
418:         if ((flags & IS_NULL) != 0) {
419:             return null;
420:         }
421: 
422:         T target;
423: 
424:         Class<?> actualSubclass = null;
425:         TypeSerializer subclassSerializer = null;
426: 
427:         if ((flags & IS_SUBCLASS) != 0) {
428:             String subclassName = source.readUTF();
429:             try {
430:                 actualSubclass = Class.forName(subclassName, true, cl);
431:             } catch (ClassNotFoundException e) {
432:                 throw new RuntimeException("Cannot instantiate class.", e);
433:             }
434:             subclassSerializer = getSubclassSerializer(actualSubclass);
435:             target = (T) subclassSerializer.createInstance();
436:             // also initialize fields for which the subclass serializer is not responsible
437:             initializeFields(target);
438:         } else if ((flags & IS_TAGGED_SUBCLASS) != 0) {
439: 
440:             int subclassTag = source.readByte();
441:             subclassSerializer = registeredSerializers[subclassTag];
442:             target = (T) subclassSerializer.createInstance();
443:             // also initialize fields for which the subclass serializer is not responsible
444:             initializeFields(target);
445:         } else {
446:             target = createInstance();
447:         }
448: 
449:         if (isRecord()) {
450:             JavaRecordBuilderFactory<T>.JavaRecordBuilder builder = recordFactory.newBuilder();
451:             for (int i = 0; i < numFields; i++) {
452:                 boolean isNull = source.readBoolean();
453:                 Object fieldValue = isNull ? null : fieldSerializers[i].deserialize(source);
454:                 if (fields[i] != null) {
455:                     builder.setField(i, fieldValue);
456:                 }
457:             }
458:             target = builder.build();
459:         } else if ((flags & NO_SUBCLASS) != 0) {
460:             try {
461:                 for (int i = 0; i < numFields; i++) {
462:                     boolean isNull = source.readBoolean();
463:                     Object fieldValue = isNull ? null : fieldSerializers[i].deserialize(source);
464:                     if (fields[i] != null) {
465:                         fields[i].set(target, fieldValue);
466:                     }
467:                 }
468:             } catch (IllegalAccessException e) {
469:                 throw new RuntimeException(
470:                         "Error during POJO copy, this should not happen since we check the fields before.",
471:                         e);
472:             }
473:         } else {
474:             if (subclassSerializer != null) {
475:                 target = (T) subclassSerializer.deserialize(target, source);
476:             }
477:         }
478:         return target;
479:     }
480: 
481:     @Override
482:     @SuppressWarnings({"unchecked", "rawtypes"})
483:     public T deserialize(T reuse, DataInputView source) throws IOException {
484: 
485:         // handle null values
486:         int flags = source.readByte();
487:         if ((flags & IS_NULL) != 0) {
488:             return null;
489:         }
490: 
491:         Class<?> subclass = null;
492:         TypeSerializer subclassSerializer = null;
493:         if ((flags & IS_SUBCLASS) != 0) {
494:             String subclassName = source.readUTF();
495:             try {
496:                 subclass = Class.forName(subclassName, true, cl);
497:             } catch (ClassNotFoundException e) {
498:                 throw new RuntimeException("Cannot instantiate class.", e);
499:             }
500:             subclassSerializer = getSubclassSerializer(subclass);
501: 
502:             if (reuse == null || subclass != reuse.getClass()) {
503:                 // cannot reuse
504:                 reuse = (T) subclassSerializer.createInstance();
505:                 // also initialize fields for which the subclass serializer is not responsible
506:                 initializeFields(reuse);
507:             }
508:         } else if ((flags & IS_TAGGED_SUBCLASS) != 0) {
509:             int subclassTag = source.readByte();
510:             subclassSerializer = registeredSerializers[subclassTag];
511: 
512:             if (reuse == null || ((PojoSerializer) subclassSerializer).clazz != reuse.getClass()) {
513:                 // cannot reuse
514:                 reuse = (T) subclassSerializer.createInstance();
515:                 // also initialize fields for which the subclass serializer is not responsible
516:                 initializeFields(reuse);
517:             }
518:         } else {
519:             if (reuse == null || clazz != reuse.getClass()) {
520:                 reuse = createInstance();
521:             }
522:         }
523: 
524:         if (isRecord()) {
525:             try {
526:                 JavaRecordBuilderFactory<T>.JavaRecordBuilder builder = recordFactory.newBuilder();
527:                 for (int i = 0; i < numFields; i++) {
528:                     boolean isNull = source.readBoolean();
529: 
530:                     if (fields[i] != null) {
531:                         if (isNull) {
532:                             builder.setField(i, null);
533:                         } else {
534:                             Object reuseField = reuse == null ? null : fields[i].get(reuse);
535:                             builder.setField(i, deserializeField(reuseField, i, source));
536:                         }
537:                     } else if (!isNull) {
538:                         // read and dump a pre-existing field value
539:                         fieldSerializers[i].deserialize(source);
540:                     }
541:                 }
542: 
543:                 reuse = builder.build();
544:             } catch (IllegalAccessException e) {
545:                 throw new RuntimeException(
546:                         "Error during POJO copy, this should not happen since we check the fields before.",
547:                         e);
548:             }
549:         } else if ((flags & NO_SUBCLASS) != 0) {
550:             try {
551:                 for (int i = 0; i < numFields; i++) {
552:                     boolean isNull = source.readBoolean();
553: 
554:                     if (fields[i] != null) {
555:                         if (isNull) {
556:                             fields[i].set(reuse, null);
557:                         } else {
558:                             fields[i].set(reuse, deserializeField(fields[i].get(reuse), i, source));
559:                         }
560:                     } else if (!isNull) {
561:                         // read and dump a pre-existing field value
562:                         fieldSerializers[i].deserialize(source);
563:                     }
564:                 }
565:             } catch (IllegalAccessException e) {
566:                 throw new RuntimeException(
567:                         "Error during POJO copy, this should not happen since we check the fields before.",
568:                         e);
569:             }
570:         } else {
571:             if (subclassSerializer != null) {
572:                 reuse = (T) subclassSerializer.deserialize(reuse, source);
573:             }
574:         }
575: 
576:         return reuse;
577:     }
578: 
579:     private Object deserializeField(Object reuseField, int i, DataInputView source)
580:             throws IllegalAccessException, IOException {
581:         if (reuseField != null) {
582:             return fieldSerializers[i].deserialize(reuseField, source);
583:         } else {
584:             return fieldSerializers[i].deserialize(source);
585:         }
586:     }
587: 
588:     @Override
589:     public void copy(DataInputView source, DataOutputView target) throws IOException {
590:         // copy the flags
591:         int flags = source.readByte();
592:         target.writeByte(flags);
593: 
594:         if ((flags & IS_NULL) != 0) {
595:             // is a null value, nothing further to copy
596:             return;
597:         }
598: 
599:         TypeSerializer<?> subclassSerializer = null;
600:         if ((flags & IS_SUBCLASS) != 0) {
601:             String className = source.readUTF();
602:             target.writeUTF(className);
603:             try {
604:                 Class<?> subclass =
605:                         Class.forName(
606:                                 className, true, Thread.currentThread().getContextClassLoader());
607:                 subclassSerializer = getSubclassSerializer(subclass);
608:             } catch (ClassNotFoundException e) {
609:                 throw new RuntimeException("Cannot instantiate class.", e);
610:             }
611:         } else if ((flags & IS_TAGGED_SUBCLASS) != 0) {
612:             int subclassTag = source.readByte();
613:             target.writeByte(subclassTag);
614:             subclassSerializer = registeredSerializers[subclassTag];
615:         }
616: 
617:         if ((flags & NO_SUBCLASS) != 0) {
618:             for (int i = 0; i < numFields; i++) {
619:                 boolean isNull = source.readBoolean();
620:                 target.writeBoolean(isNull);
621:                 if (!isNull) {
622:                     fieldSerializers[i].copy(source, target);
623:                 }
624:             }
625:         } else {
626:             if (subclassSerializer != null) {
627:                 subclassSerializer.copy(source, target);
628:             }
629:         }
630:     }
631: 
632:     @Override
633:     public int hashCode() {
634:         return 31
635:                         * (31 * Arrays.hashCode(fieldSerializers)
636:                                 + Arrays.hashCode(registeredSerializers))
637:                 + Objects.hash(clazz, numFields, registeredClasses);
638:     }
639: 
640:     @Override
641:     public boolean equals(Object obj) {
642:         if (obj instanceof PojoSerializer) {
643:             PojoSerializer<?> other = (PojoSerializer<?>) obj;
644: 
645:             return clazz == other.clazz
646:                     && Arrays.equals(fieldSerializers, other.fieldSerializers)
647:                     && Arrays.equals(registeredSerializers, other.registeredSerializers)
648:                     && numFields == other.numFields
649:                     && registeredClasses.equals(other.registeredClasses);
650:         } else {
651:             return false;
652:         }
653:     }
