673:     private void writeObject(ObjectOutputStream out) throws IOException, ClassNotFoundException {
674:         out.defaultWriteObject();
675:         out.writeInt(fields.length);
676:         for (Field field : fields) {
677:             FieldSerializer.serializeField(field, out);
678:         }
679:     }
680: 
681:     private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
682:         in.defaultReadObject();
683:         int numFields = in.readInt();
684:         fields = new Field[numFields];
685:         for (int i = 0; i < numFields; i++) {
686:             // the deserialized Field may be null if the field no longer exists in the POJO;
687:             // in this case, when de-/serializing and copying instances using this serializer
688:             // instance, the missing fields will simply be skipped
689:             fields[i] = FieldSerializer.deserializeField(in);
690:         }
691: 
692:         cl = Thread.currentThread().getContextClassLoader();
693:         subclassSerializerCache = new HashMap<>();
694:         if (TypeExtractor.isRecord(clazz)) {
695:             this.recordFactory = JavaRecordBuilderFactory.create(clazz, fields);
696:         }
697:     }
