756:                 CollectionUtil.newLinkedHashSetWithExpectedSize(
757:                         executionConfig.getRegisteredPojoTypes().size());
758:         for (Class<?> registeredClass : executionConfig.getRegisteredPojoTypes()) {
759:             if (registeredClass.equals(basePojoClass)) {
760:                 continue;
