861:     private static <T> PojoSerializerSnapshot<T> buildSnapshot(
862:             Class<T> pojoType,
863:             LinkedHashMap<Class<?>, Integer> registeredSubclassesToTags,
864:             TypeSerializer<?>[] registeredSubclassSerializers,
