310:         // the present entries dictates the preexisting fields, because removed fields would be
311:         // represented as absent keys in the optional map.
312:         final Set<LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>>>
313:                 presentFieldSnapshots = oldFieldSerializerSnapshots.getPresentEntries();
314: 
315:         final ArrayList<TypeSerializerSnapshot<?>> associatedFieldSerializerSnapshots =
316:                 new ArrayList<>(presentFieldSnapshots.size());
