320:         Map<Field, TypeSerializerSnapshot<?>> newFieldSerializerSnapshots =
321:                 snapshotData.getFieldSerializerSnapshots().unwrapOptionals();
322:         for (LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>> presentFieldEntry :
323:                 presentFieldSnapshots) {
324:             TypeSerializerSnapshot<?> associatedNewFieldSerializer =
325:                     newFieldSerializerSnapshots.get(presentFieldEntry.getKey());
326:             checkState(
327:                     associatedNewFieldSerializer != null,
328:                     "a present field should have its associated new field serializer available.");
329: 
330:             associatedFieldSerializerSnapshots.add(presentFieldEntry.getValue());
331:             associatedNewFieldSerializerSnapshots.add(associatedNewFieldSerializer);
