126:      * Creates a lazy {@link ExecutionConfig} that contains options for {@link TypeSerializer}s with
127:      * information from existing {@link ExecutionConfig} (if available) enriched with table {@link
128:      * ReadableConfig}.
129:      */
130:     private static Supplier<ExecutionConfig> createSerializerExecutionConfig(
131:             ClassLoader classLoader, ReadableConfig config, ExecutionConfig serializerConfig) {
132:         return () -> {
133:             final ExecutionConfig newExecutionConfig = new ExecutionConfig();
134: 
135:             if (serializerConfig != null) {
136:                 if (serializerConfig.isForceKryoEnabled()) {
137:                     newExecutionConfig.enableForceKryo();
138:                 }
139: 
140:                 if (serializerConfig.isForceAvroEnabled()) {
141:                     newExecutionConfig.enableForceAvro();
142:                 }
143: 
144:                 serializerConfig
145:                         .getDefaultKryoSerializers()
146:                         .forEach(
147:                                 (c, s) ->
148:                                         newExecutionConfig.addDefaultKryoSerializer(
149:                                                 c, s.getSerializer()));
150: 
151:                 serializerConfig
152:                         .getDefaultKryoSerializerClasses()
153:                         .forEach(newExecutionConfig::addDefaultKryoSerializer);
154: 
155:                 serializerConfig
156:                         .getRegisteredKryoTypes()
157:                         .forEach(newExecutionConfig::registerKryoType);
158: 
159:                 serializerConfig
160:                         .getRegisteredTypesWithKryoSerializerClasses()
161:                         .forEach(newExecutionConfig::registerTypeWithKryoSerializer);
162: 
163:                 serializerConfig
164:                         .getRegisteredTypesWithKryoSerializers()
165:                         .forEach(
166:                                 (c, s) ->
167:                                         newExecutionConfig.registerTypeWithKryoSerializer(
168:                                                 c, s.getSerializer()));
169:             }
170: 
171:             newExecutionConfig.configure(config, classLoader);
172: 
173:             return newExecutionConfig;
174:         };
175:     }
