490:     /**
491:      * Tests that: - Previous Pojo serializer did not have registrations, and created cached
492:      * serializers for subclasses - On restore, it had those subclasses registered
493:      *
494:      * <p>In this case, after reconfiguration, the cache should be repopulated, and registrations
495:      * should also exist for the subclasses.
496:      *
497:      * <p>Note: the cache still needs to be repopulated because previous data of those subclasses
498:      * were written with the cached serializers. In this case, the repopulated cache has
499:      * reconfigured serializers for the subclasses so that previous written data can be read, but
500:      * the registered serializers for the subclasses do not necessarily need to be reconfigured
501:      * since they will only be used to write new data.
502:      */
503:     @Test
504:     void testReconfigureWithPreviouslyNonregisteredSubclasses() throws Exception {
505:         // don't register any subclasses at first
506:         PojoSerializer<TestUserClass> pojoSerializer =
507:                 (PojoSerializer<TestUserClass>) type.createSerializer(new ExecutionConfig());
508: 
509:         // create cached serializers for SubTestUserClassA and SubTestUserClassB
510:         pojoSerializer.getSubclassSerializer(SubTestUserClassA.class);
511:         pojoSerializer.getSubclassSerializer(SubTestUserClassB.class);
512: 
513:         // make sure serializers are in cache
514:         assertThat(pojoSerializer.getSubclassSerializerCache())
515:                 .containsOnlyKeys(SubTestUserClassA.class, SubTestUserClassB.class);
516: 
517:         // make sure that registrations are empty
518:         assertThat(pojoSerializer.getRegisteredClasses()).isEmpty();
519:         assertThat(pojoSerializer.getRegisteredSerializers()).isEmpty();
520: 
521:         // snapshot configuration and serialize to bytes
522:         TypeSerializerSnapshot pojoSerializerConfigSnapshot =
523:                 pojoSerializer.snapshotConfiguration();
524:         byte[] serializedConfig;
525:         try (ByteArrayOutputStream out = new ByteArrayOutputStream()) {
526:             TypeSerializerSnapshotSerializationUtil.writeSerializerSnapshot(
527:                     new DataOutputViewStreamWrapper(out), pojoSerializerConfigSnapshot);
528:             serializedConfig = out.toByteArray();
529:         }
530: 
531:         // instantiate new PojoSerializer, with new execution config that has the subclass
532:         // registrations
533:         ExecutionConfig serializerConfig = new ExecutionConfig();
534:         serializerConfig.registerPojoType(SubTestUserClassA.class);
535:         serializerConfig.registerPojoType(SubTestUserClassB.class);
536:         pojoSerializer = (PojoSerializer<TestUserClass>) type.createSerializer(serializerConfig);
537: 
538:         // read configuration from bytes
539:         try (ByteArrayInputStream in = new ByteArrayInputStream(serializedConfig)) {
540:             pojoSerializerConfigSnapshot =
541:                     TypeSerializerSnapshotSerializationUtil.readSerializerSnapshot(
542:                             new DataInputViewStreamWrapper(in),
543:                             Thread.currentThread().getContextClassLoader());
544:         }
545: 
546:         // reconfigure - check reconfiguration result and that
547:         // 1) subclass serializer cache is repopulated
548:         // 2) registrations also contain the now registered subclasses
549:         @SuppressWarnings("unchecked")
550:         TypeSerializerSchemaCompatibility<TestUserClass> compatResult =
551:                 pojoSerializer
552:                         .snapshotConfiguration()
553:                         .resolveSchemaCompatibility(pojoSerializerConfigSnapshot);
554:         assertThat(compatResult.isCompatibleWithReconfiguredSerializer()).isTrue();
555:         assertThat(compatResult.getReconfiguredSerializer()).isInstanceOf(PojoSerializer.class);
556: 
557:         PojoSerializer<TestUserClass> reconfiguredPojoSerializer =
558:                 (PojoSerializer<TestUserClass>) compatResult.getReconfiguredSerializer();
559: 
560:         assertThat(reconfiguredPojoSerializer.getSubclassSerializerCache())
561:                 .containsOnlyKeys(SubTestUserClassA.class, SubTestUserClassB.class);
562: 
563:         assertThat(reconfiguredPojoSerializer.getRegisteredClasses())
564:                 .containsOnlyKeys(SubTestUserClassA.class, SubTestUserClassB.class);
565:     }
